function a(t){const r=Date.now()-t,e=Math.floor(r/6e4),n=Math.floor(r/36e5),o=Math.floor(r/864e5);return e<2?"just now":e<60?`${e} minutes ago`:n<24?`${n} hours ago`:`${o} days ago`}function u(t){const r=Math.floor(t/60),e=t%60;return`${r}:${e.toString().padStart(2,"0")}`}function i(t,r,e){return r===0?"Perfect":((t+e)/r).toFixed(1)}function s(t){switch(t){case"CLASSIC":return"Ranked Solo";case"ARAM":return"ARAM";default:return t}}function f(t){return t?t.charAt(0).toUpperCase()+t.slice(1).toLowerCase():""}function c(t){return t.replace(/<[^>]*>/g,"")}export{s as a,u as b,f as c,i as f,a as r,c as s};
